	*/
	readonly gridTemplateRows?: string;

	/**
	Sets the column position of a grid item. Accepts a single 1-based index or a `"start / end"` string.
	*/
	readonly gridColumn?: number | string;

	/**
	Sets the row position of a grid item. Accepts a single 1-based index or a `"start / end"` string.
	*/
	readonly gridRow?: number | string;

	/**
	Add a border with a specified style.",
)

