    "if ('display' in style) {
		node.setDisplay(
			style.display === 'flex' ? Yoga.DISPLAY_FLEX : Yoga.DISPLAY_NONE,
		);
	}",
    "if ('display' in style) {
		node.setDisplay(
			style.display === 'none' ? Yoga.DISPLAY_NONE : Yoga.DISPLAY_FLEX,
		);
	}",
)

with open(path, 'w') as f:
    f.write(src)
print("done")
